update public.national_ingestion_source_policies set quota_mode='runtime_or_legacy',daily_request_limit=50,hourly_request_limit=30,notes='Use the production Data.gov v4 API when DATA_GOV_API_KEY is configured. Until then, continue the existing read-only CKAN catalog integration under a conservative 30/hour, 50/day application budget; do not automate with DEMO_KEY.',updated_at=now() where source_key='data_gov';
